operations.search:
/* ----------------------------------------------------------
   Cross first Speed threshold
   ---------------------------------------------------------- */

if (
  newTotal > standardAllowance &&
  getFrameConnTurnStateMovementBoostCount(
    state
  ) < 1
) {
  const result =
    ensureFrameConnTurnStateAutomaticMovementBoost(
      state,
      {
        forceOvercharge:
          false
      }
    );


  automaticActions.push({
    threshold:
      standardAllowance,

    ...result
  });
}


/* ----------------------------------------------------------
   Cross second Speed threshold
   ---------------------------------------------------------- */

if (
  newTotal >
    standardAllowance +
      speed &&
  getFrameConnTurnStateMovementBoostCount(
    state
  ) < 2
) {
  const result =
    ensureFrameConnTurnStateAutomaticMovementBoost(
      state,
      {
        forceOvercharge:
          true
      }
    );


  automaticActions.push({
    threshold:
      standardAllowance +
        speed,

    ...result
  });
}

